/**
 * The site's side of Strapi (the headless counterpart of the WordPress bridge):
 *
 * - change notifications: every write to content (publish, update, delete, media) sends
 *   one signed POST to the site, which clears its page cache (debounced);
 * - languages: the site's locales exist in Strapi, the site's default is Strapi's default;
 * - editor labels: the site pages' fields (generated by `npm run strapi:fields`) get
 *   readable labels and show the site's own copy as the placeholder;
 * - shared images: image slots that are one picture on two site pages (editable-pages.ts
 *   `sameAs`, e.g. a home grid and the page it previews) are kept in step on every save.
 */
const { AsyncLocalStorage } = require("node:async_hooks");
const { createHmac } = require("node:crypto");
const sitePages = require("./site-pages.json");

// Comma-separated: one Strapi can serve several copies of the site (development and production).
const WEBHOOK_URLS = (process.env.HEADLESS_WEBHOOK_URL || "").split(",").map((url) => url.trim()).filter(Boolean);
const WEBHOOK_SECRET = process.env.HEADLESS_WEBHOOK_SECRET || "";
const WRITE_ACTIONS = new Set(["create", "update", "delete", "publish", "unpublish", "discardDraft"]);

let pending = null;
let changed = new Set();

/** One notification per burst of writes (publishing a localized entry is several writes). */
function notifySite(strapi, uid) {
  if (!WEBHOOK_URLS.length || !WEBHOOK_SECRET) return;
  changed.add(uid);
  if (pending) return;
  pending = setTimeout(async () => {
    const body = JSON.stringify({ event: "change", models: [...changed], at: new Date().toISOString() });
    const signature = createHmac("sha256", WEBHOOK_SECRET).update(body, "utf8").digest("base64");
    pending = null;
    changed = new Set();
    await Promise.all(
      WEBHOOK_URLS.map(async (url) => {
        try {
          const response = await fetch(url, {
            method: "POST",
            headers: { "Content-Type": "application/json", "X-Headless-Signature": signature },
            body,
            signal: AbortSignal.timeout(5000),
          });
          if (!response.ok) strapi.log.warn(`[headless] ${url} answered ${response.status} to the change notification`);
        } catch (error) {
          strapi.log.warn(`[headless] change notification to ${url} failed: ${error.message}`);
        }
      }),
    );
  }, 300);
}

async function ensureLocales(strapi) {
  const service = strapi.plugin("i18n").service("locales");
  const names = new Intl.DisplayNames(["en"], { type: "language" });
  for (const code of sitePages.locales) {
    if (!(await service.findByCode(code))) await service.create({ code, name: `${names.of(code) ?? code} (${code})` });
  }
  if ((await service.getDefaultLocale()) !== sitePages.defaultLocale) await service.setDefaultLocale({ code: sitePages.defaultLocale });
}

/** Labels, placeholders and descriptions from site-pages.json, on generated types and components. */
async function applyFieldLabels(strapi) {
  const contentManager = strapi.plugin("content-manager");
  const apply = async (service, model, fields) => {
    if (!model) return;
    const configuration = await service.findConfiguration(model);
    const metadatas = configuration.metadatas ?? {};
    let dirty = false;
    for (const [attribute, meta] of Object.entries(fields)) {
      const edit = metadatas[attribute]?.edit;
      if (!edit) continue;
      for (const [key, value] of Object.entries({ label: meta.label, placeholder: meta.placeholder ?? "", description: meta.description ?? "" })) {
        if (edit[key] !== value) {
          edit[key] = value;
          dirty = true;
        }
      }
    }
    const mainField = Object.entries(fields).find(([, meta]) => meta.mainField)?.[0];
    if (mainField && configuration.settings?.mainField !== mainField) {
      configuration.settings.mainField = mainField;
      dirty = true;
    }
    if (dirty) await service.updateConfiguration(model, { settings: configuration.settings, metadatas, layouts: configuration.layouts });
  };
  for (const [uid, fields] of Object.entries(sitePages.labels ?? {})) {
    try {
      if (strapi.contentTypes[uid]) await apply(contentManager.service("content-types"), strapi.contentTypes[uid], fields);
      else if (strapi.components[uid]) await apply(contentManager.service("components"), strapi.components[uid], fields);
    } catch (error) {
      strapi.log.warn(`[headless] labels for ${uid}: ${error.message}`);
    }
  }
}

// ---------------------------------------------------------------- shared images

const pageOfUid = new Map(Object.entries(sitePages.pages ?? {}).map(([key, page]) => [page.uid, key]));
// Both directions: a save on either page updates the other.
const LINKS = (sitePages.links ?? []).flatMap((link) => [link, { from: link.to, to: link.from, by: link.by }]);
const mirroring = new AsyncLocalStorage();

/** Every component and media of these fields, populated (the update sends all of it back). */
function populateOf(fields) {
  const populate = {};
  for (const field of fields) {
    if (field.kind === "group" || field.kind === "list") {
      const nested = populateOf(field.fields);
      populate[field.attr] = Object.keys(nested).length ? { populate: nested } : true;
    } else if (field.kind !== "value") {
      populate[field.attr] = true;
    }
  }
  return populate;
}

/** A copy path ("divisions.items.image") as the fields along it, from the page's top level. */
function fieldsAlong(page, dotPath) {
  let fields = sitePages.pages[page]?.fields ?? [];
  const chain = [];
  for (const key of dotPath.split(".")) {
    const field = fields.find((candidate) => candidate.key === key);
    if (!field) return null;
    chain.push(field);
    fields = field.fields ?? [];
  }
  return chain;
}

/** The objects holding the image (the list items), walking groups and lists along the chain. */
function holders(value, chain) {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap((item) => holders(item, chain));
  if (chain.length === 1) return [value];
  return holders(value[chain[0].attr], chain.slice(1));
}

/** The value as an update takes it back: component ids kept, media as ids. */
function forUpdate(value, fields) {
  if (Array.isArray(value)) return value.map((item) => forUpdate(item, fields));
  if (!value || typeof value !== "object") return value;
  const out = value.id ? { id: value.id } : {};
  for (const field of fields) {
    const current = value[field.attr];
    if (current === undefined) continue;
    if (field.kind === "image") out[field.attr] = current?.id ?? null;
    else if (field.kind === "gallery") out[field.attr] = (current ?? []).map((media) => media.id);
    else if (field.kind === "group" || field.kind === "list") out[field.attr] = current === null ? null : forUpdate(current, field.fields);
    else if (field.kind === "strings") out[field.attr] = (current ?? []).map(({ id, value: text }) => ({ id, value: text }));
    else out[field.attr] = current;
  }
  return out;
}

async function loadPage(strapi, page, locale, topField) {
  const { uid } = sitePages.pages[page];
  const nested = populateOf(topField.fields ?? []);
  return strapi.documents(uid).findFirst({ locale, populate: { [topField.attr]: Object.keys(nested).length ? { populate: nested } : true } });
}

const imageAttr = (chain) => chain[chain.length - 1].attr;
const byAttr = (chain, by) => (chain[chain.length - 2]?.fields ?? []).find((field) => field.key === by)?.attr;

/** For each link from `page`: its items' images by their `by` value (null: no image). */
async function sharedPictures(strapi, page, locale) {
  const shares = [];
  for (const link of LINKS.filter((candidate) => candidate.from.page === page)) {
    const from = fieldsAlong(link.from.page, link.from.path);
    if (!from) continue;
    const source = await loadPage(strapi, page, locale, from[0]);
    const pictures = new Map();
    for (const item of holders(source?.[from[0].attr], from.slice(1))) {
      const key = item[byAttr(from, link.by)];
      if (key) pictures.set(key, item[imageAttr(from)] ?? null);
    }
    shares.push({ link, pictures });
  }
  return shares;
}

/** After a save: the images the editor changed on `page`, set on the other page's matching items. */
async function mirrorSharedImages(strapi, page, locale, before) {
  for (const { link, pictures } of await sharedPictures(strapi, page, locale)) {
    const previous = before.find((share) => share.link === link)?.pictures ?? new Map();
    const changed = [...pictures].filter(([key, media]) => (media?.id ?? null) !== (previous.get(key)?.id ?? null));
    if (!changed.length) continue;
    const to = fieldsAlong(link.to.page, link.to.path);
    const target = to && (await loadPage(strapi, link.to.page, locale, to[0]));
    if (!target) continue;
    const chosen = new Map(changed);
    let dirty = false;
    for (const item of holders(target[to[0].attr], to.slice(1))) {
      const key = item[byAttr(to, link.by)];
      if (!chosen.has(key) || (item[imageAttr(to)]?.id ?? null) === (chosen.get(key)?.id ?? null)) continue;
      item[imageAttr(to)] = chosen.get(key);
      dirty = true;
    }
    if (!dirty) continue;
    await mirroring.run(true, () =>
      strapi.documents(sitePages.pages[link.to.page].uid).update({ documentId: target.documentId, locale, data: { [to[0].attr]: forUpdate(target[to[0].attr], to[0].fields ?? []) } }),
    );
    strapi.log.info(`[headless] shared images: ${link.from.page} → ${link.to.page} (${locale}): ${changed.map(([key]) => key).join(", ")}`);
  }
}

module.exports = {
  register({ strapi }) {
    strapi.documents.use(async (context, next) => {
      // Saves of a page with shared images (not strapi:sync filling defaults, not a copy made here).
      const page = pageOfUid.get(context.uid);
      const locale = context.params?.locale ?? sitePages.defaultLocale;
      const shares =
        page && (context.action === "update" || context.action === "create") && !mirroring.getStore() && !strapi.requestContext.get()?.get("x-site-sync") && LINKS.some((link) => link.from.page === page);
      const before = shares ? await sharedPictures(strapi, page, locale).catch(() => null) : null;
      const result = await next();
      if (context.uid.startsWith("api::") && WRITE_ACTIONS.has(context.action)) notifySite(strapi, context.uid);
      if (before) {
        try {
          await mirrorSharedImages(strapi, page, locale, before);
        } catch (error) {
          strapi.log.warn(`[headless] shared images from ${page}: ${error.message}`);
        }
      }
      return result;
    });
    // Replacing an image or editing its alt text changes pages that show it.
    strapi.db.lifecycles.subscribe({
      models: ["plugin::upload.file"],
      afterUpdate: () => notifySite(strapi, "plugin::upload.file"),
      afterDelete: () => notifySite(strapi, "plugin::upload.file"),
    });
  },

  async bootstrap({ strapi }) {
    await ensureLocales(strapi);
    await applyFieldLabels(strapi);
    if (!WEBHOOK_URLS.length || !WEBHOOK_SECRET) strapi.log.warn("[headless] HEADLESS_WEBHOOK_URL / HEADLESS_WEBHOOK_SECRET not set: the site learns about edits only when its cache expires.");
  },
};
